const items = $input.all();

// Separar bundle y actos
const bundleItem = items.find(i => i.json.correction_prompt);
const actItems = items.filter(i => i.json.act_number !== undefined);

if (!bundleItem) {
  throw new Error("No se encontró prompt_bundle");
}

if (actItems.length === 0) {
  throw new Error("No hay actos");
}

const bundle = bundleItem.json;

// Fan-out manual (equivalente a multiplex)
return actItems.map(act => {
  return {
    json: {
      ...act.json,
      correction_prompt: bundle.correction_prompt,
    }
  };
});

const data = $json;

// Validaciones mínimas
if (!data.correction_prompt) {
  throw new Error("Falta correction_prompt");
}

if (!data.chapter) {
  throw new Error("Falta chapter");
}

// Inyección
const prompt = data.correction_prompt.replace(/{{text}}/g, data.chapter);

// Output mínimo (token-efficient + persistencia ready)
return [
  {
    json: {
      id_story: data.id_story,
      act_number: data.act_number,
      prompt
    }
  }
];

// Función principal robusta para extraer JSON
function extractJSON(rawText) {
  if (!rawText || typeof rawText !== 'string') return null;

  // 1. Limpieza inicial: Eliminar bloques de markdown ```json ... ```
  let text = rawText.replace(/```json/g, '').replace(/```/g, '');

  // 2. Estrategia A: Intento directo (si el modelo se portó bien)
  try {
    return JSON.parse(text);
  } catch (e) {
    // Falló, pasamos a la estrategia B
  }

  // 3. Estrategia B: Extracción forzada por balance de llaves {}
  // Buscamos el primer { y contamos hasta cerrar el objeto, ignorando el texto conversacional alrededor.
  const firstOpen = text.indexOf('{');
  if (firstOpen !== -1) {
    let depth = 0;
    let inString = false;
    let escape = false;
    let jsonEnd = -1;

    for (let i = firstOpen; i < text.length; i++) {
      const char = text[i];

      if (escape) {
        escape = false;
        continue;
      }
      if (char === '\\') {
        escape = true;
        continue;
      }
      if (char === '"') {
        inString = !inString;
        continue;
      }
      if (!inString) {
        if (char === '{') depth++;
        if (char === '}') depth--;

        if (depth === 0) {
          jsonEnd = i;
          break;
        }
      }
    }

    if (jsonEnd !== -1) {
      const jsonString = text.slice(firstOpen, jsonEnd + 1);

      // 4. Estrategia C: Corrección de errores comunes antes de parsear
      // Muchos LLMs ponen comas al final de los últimos objetos { "a": 1, } -> esto es inválido en JSON estándar
      const fixedJson = jsonString.replace(/,(\s*[}\]])/g, '$1');

      try {
        return JSON.parse(fixedJson);
      } catch (e) {
        // Si falla incluso con la corrección, intentamos parsearlo como 'JSON suelto'
        // a veces el modelo devuelve: "corrected_text": "..." sin las llaves externas
        try {
           // Intento desesperado: buscar el valor directamente si es un string simple
           const match = jsonString.match(/"corrected_text"\s*:\s*"([^"]*(?:\\.[^"]*)*)"/);
           if (match && match[1]) {
             // Restaurar saltos de línea escapados \n -> reales, si es necesario, 
             // pero normalmente JSON.parse lo maneja. Aquí devolvemos un objeto mock.
             return { corrected_text: JSON.parse(`"${match[1]}"`) }; 
           }
        } catch(err) {}
      }
    }
  }

  return null;
}

// --- LÓGICA PRINCIPAL DEL NODO ---

// 1. Obtenemos la entrada. Puede venir en $json.output, $json.text o $json.response
const rawInput = $json.output || $json.text || $json.response || "";

// 2. Ejecutamos el extractor robusto
let parsedData = extractJSON(rawInput);

// 3. Si falla TODO, intentamos ver si el input crudo ya es el objeto (caso raro de doble parseo)
if (!parsedData && typeof rawInput === 'object') {
    parsedData = rawInput;
}

// 4. Validación y manejo de errores
if (!parsedData || !parsedData.corrected_text) {
  // Opción A: Lanzar error (detiene el flujo)
  // throw new Error("No se pudo parsear el JSON del LLM. Input: " + rawInput.substring(0, 100));

  // Opción B: Devolver el texto crudo en un campo 'fallback' para que el flujo no se detenga
  // ¡Útil si no quieres perder el progreso de los 5 actos por uno fallido!
  return [
    {
      json: {
        id_story: $json.id_story,
        act_number: $json.act_number,
        corrected_text: rawInput, // Usamos el texto sucio como último recurso
        parsing_error: true
      }
    }
  ];
}

// 5. Éxito: Retornamos el objeto limpio
return [
  {
    json: {
      id_story: $json.id_story,
      act_number: $json.act_number,
      corrected_text: parsedData.corrected_text
    }
  }
];

// 1. Recuperamos todos los items que llegan a este nodo
// En un nodo Code de n8n, 'items' es el array que contiene todos los elementos entrantes.
const allItems = items;

// 2. Ordenamos los items por 'act_number' para mantener el orden narrativo
// Esto es crucial porque a veces los procesos asíncronos pueden desordenar la llegada.
const sortedItems = allItems.sort((a, b) => {
  const numA = a.json.act_number || 0;
  const numB = b.json.act_number || 0;
  return numA - numB;
});

// 3. Extraemos los textos y los unimos
// Usamos .map() para obtener solo el texto de cada item
// Usamos .join("\n\n") para pegarlos con un salto de línea entre actos
const fullStory = sortedItems
  .map(item => item.json.corrected_text || "")
  .join("\n\n");

// 4. Retornamos el array con un único objeto con la estructura deseada
return [
  {
    json: {
      relato: fullStory
    }
  }
];

const data = $json;

// Validaciones
if (!data.relato) {
  throw new Error("Falta full_text");
}

if (!data.detection_prompt) {
  throw new Error("Falta detection_prompt");
}

// Inyección
let prompt = data.detection_prompt.replace(/{{text}}/g, data.relato.trim());

// Output mínimo
return [
  {
    json: {
      prompt
    }
  }
];

const raw = $json.text || "";

// 1. Limpiar basura común
let cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// 2. Intentar parse directo
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {

  // 3. Buscar JSON interno
  const match = cleaned.match(/\{[\s\S]*\}/);

  if (!match) {
    // fallback seguro
    return [
      {
        json: {
          issues: [],
          warning: "No se pudo parsear JSON de detection"
        }
      }
    ];
  }

  try {
    parsed = JSON.parse(match[0]);
  } catch (e2) {
    return [
      {
        json: {
          issues: [],
          warning: "JSON inválido en detection"
        }
      }
    ];
  }
}

// 4. Validación estructural
if (!parsed.issues || !Array.isArray(parsed.issues)) {
  return [
    {
      json: {
        issues: [],
        warning: "No se encontraron issues válidos"
      }
    }
  ];
}

// 5. Normalización (muy importante)
const normalizedIssues = parsed.issues.map(issue => ({
  type: issue.type || "unknown",
  description: issue.description || "",
  location: issue.location || "unknown",
  severity: normalizeSeverity(issue.severity)
}));

function normalizeSeverity(sev) {
  if (!sev) return "media";

  const s = sev.toLowerCase();

  if (s.includes("alta")) return "alta";
  if (s.includes("baja")) return "baja";

  return "media";
}

// 6. Output limpio
return [
  {
    json: {
      id_story: $json.id_story,
      issues: normalizedIssues
    }
  }
];

const data = $json;

// Validaciones duras
if (!data.relato) {
  throw new Error("Falta el relato");
}

if (!data.issues) {
  throw new Error("Faltan issues");
}

if (!data.resolution_prompt) {
  throw new Error("Falta resolution_prompt");
}

// Serializar issues (clave para el LLM)
const issuesString = JSON.stringify(data.issues, null, 2);

// Inyección en template
let prompt = data.resolution_prompt
  .replace(/{{text}}/g, data.relato.trim())
  .replace(/{{issues}}/g, issuesString);

// Output mínimo y limpio
return [
  {
    json: {
      id_story: data.id_story,
      prompt
    }
  }
];

// ---------------------------------------------------------
// FUNCIÓN AUXILIAR: Reparar comillas no escapadas (Crucial para diálogos)
// ---------------------------------------------------------
function fixJsonString(jsonStr) {
  const key = 'sanitized_text';
  // Buscamos la clave "sanitized_text":
  const keyPattern = `"${key}"\\s*:\\s*"`;
  const matchStart = jsonStr.search(keyPattern);

  if (matchStart !== -1) {
    // Calculamos dónde empieza el contenido del texto (después de las comillas)
    const valueStartIndex = matchStart + jsonStr.match(keyPattern)[0].length;

    // Buscamos el cierre REAL del valor (una comilla seguida de , o })
    for (let i = valueStartIndex; i < jsonStr.length; i++) {
      if (jsonStr[i] === '"') {
        const remainder = jsonStr.substring(i + 1).trim();
        if (remainder.startsWith(',') || remainder.startsWith('}')) {
          // Extraemos solo el relato
          const rawContent = jsonStr.substring(valueStartIndex, i);

          // 1. Escapamos comillas internas " -> \"
          // 2. Escapamos barras invertidas \ -> \\
          const fixedContent = rawContent
          .replace(/\\/g, '\\\\')
          .replace(/(?<!\\)"/g, '\\"');

          // Reconstruimos el JSON limpio
          const before = jsonStr.substring(0, valueStartIndex);
          const after = jsonStr.substring(i);

          return before + fixedContent + after;
        }
      }
    }
  }
  return jsonStr;
}

// ---------------------------------------------------------
// LÓGICA PRINCIPAL
// ---------------------------------------------------------

// 1. EXTRACCIÓN DIRECTA
// Tu estructura es [{"text": "..."}], así que accedemos a $json.text
const raw = $json.text;

if (!raw) {
  return [{ json: { sanitized_text: "", warning: "Input 'text' vacío" }}];
}

// 2. LIMPIEZA DE MARKDOWN
// Quitamos los ```json y ``` del principio y final
let cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

// 3. PARSEO ROBUSTO (Intento directo -> Reparación -> Último recurso)
try {
  // Intento A: El JSON está bien formado
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Intento B: El JSON tiene comillas sin escapar (diálogos), lo arreglamos
  const fixedJson = fixJsonString(cleaned);

  try {
    parsed = JSON.parse(fixedJson);
  } catch (e2) {
    // Intento C: Usar 'new Function' como último desesperado
    try {
      parsed = new Function('return ' + fixedJson)();
    } catch (e3) {
      return [{ json: { sanitized_text: "", warning: "Error crítico: No se pudo parsear el JSON" }}];
    }
  }
}

// 4. SALIDA FINAL
// Devolvemos exactamente el formato que pediste: [{"sanitized_text": "..."}]
return [{
  json: {
    sanitized_text: parsed.sanitized_text || ""
  }
}];

const data = $json;

// Validaciones duras
if (!data.sanitized_text) {
  throw new Error("Falta sanitized_text");
}

if (!data.validation_prompt) {
  throw new Error("Falta validation_prompt");
}

// Inyección
let prompt = data.validation_prompt
  .replace(/{{text}}/g, data.sanitized_text.trim());

// Output limpio
return [
  {
    json: {
      prompt
    }
  }
];

// ---------------------------------------------------------
// 1. EXTRACCIÓN
// ---------------------------------------------------------
// Obtenemos la respuesta. Normalmente vendrá en $json.output si usaste Output Parser,
// o en $json.text si es respuesta cruda.
const raw = $json.output || $json.text || "";

if (!raw) {
  return [{ json: { is_valid: false, notes: "Error: No se recibió respuesta del validador." } }];
}

// ---------------------------------------------------------
// 2. LIMPIEZA DE MARKDOWN
// ---------------------------------------------------------
let cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// ---------------------------------------------------------
// 3. EXTRACCIÓN DEL JSON
// ---------------------------------------------------------
// Buscamos el objeto JSON completo entre las llaves { ... }
const match = cleaned.match(/\{[\s\S]*\}/);

if (!match) {
  return [{ json: { is_valid: false, notes: "Error: Formato JSON no encontrado en validación." } }];
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (e) {
  // Si falla el parseo, asumimos lo peor para no pasar un relato corrupto
  return [{ json: { is_valid: false, notes: "Error: JSON inválido en respuesta de validación." } }];
}

// ---------------------------------------------------------
// 4. NORMALIZACIÓN DE DATOS
// ---------------------------------------------------------
// Aseguramos que is_valid sea un booleano real, no un string "true"/"false"
let isValid = parsed.is_valid;

if (typeof isValid === 'string') {
  isValid = isValid.toLowerCase() === 'true';
}

// Aseguramos que existan las notas
let notes = parsed.notes || "";

// ---------------------------------------------------------
// 5. OUTPUT
// ---------------------------------------------------------
// Mantenemos el id_story para los siguientes pasos de Persistencia
return [
  {
    json: {
      id_story: $json.id_story, // Preservamos el ID
      is_valid: isValid,        // Será TRUE o FALSE (booleano)
      notes: notes
    }
  }
];

const items = $input.all();

let correction = "";
let detection = "";
let resolution = "";
let validation = "";

// Config (último item)
const config = items.find(i => i.json.id_story)?.json;

if (!config) {
  throw new Error("No se encontró config con id_story");
}

for (let i = 0; i < items.length; i++) {

  const item = items[i];

  if (!item.binary || !item.binary.data) {
    continue;
  }

  const fileName = item.binary.data.fileName;

  const buffer = await this.helpers.getBinaryDataBuffer(i, "data");
  const text = buffer.toString("utf8").trim();

  if (fileName === config.correction_prompt_file) {
    correction = text;
    continue;
  }

  if (fileName === config.detection_prompt_file) {
    detection = text;
    continue;
  }

  if (fileName === config.resolution_prompt_file) {
    resolution = text;
    continue;
  }

  if (fileName === config.validation_prompt_file) {
    validation = text;
    continue;
  }
}

// Validación
if (!correction || !detection || !resolution || !validation) {
  throw new Error("Faltan prompts. Revisar nodo Read Files");
}

return [
  {
    json: {
      id_story: config.id_story,
      correction_prompt: correction,
      detection_prompt: detection,
      resolution_prompt: resolution,
      validation_prompt: validation
    }
  }
];

// ---------------------------------------------------------
// 1. OBTENER DATOS
// ---------------------------------------------------------
const data = $json;

const idStory = data.id_story || "sin_id";

// ---------------------------------------------------------
// 2. GESTIÓN DE VERSIÓN (Auto-incremental simulado)
// ---------------------------------------------------------
// Como el nodo Code no recuerda ejecuciones pasadas, necesitamos
// que la versión venga de un nodo "Postgres: get_next_version".
//
// Si existe el campo 'version' en el input, úsalo. Si no, asume v1.
const version = data.version || 1;

// ---------------------------------------------------------
// 3. CONTENIDO DEL ARCHIVO
// ---------------------------------------------------------
// Usamos directamente el texto sanitizado completo, sin separar en actos.
const storyContent = data.sanitized_text || "";

// ---------------------------------------------------------
// 4. NOMBRE DE ARCHIVO Y SALIDA
// ---------------------------------------------------------
// Formato solicitado: id_story + _saneado_version_X.md
const fileName = `${idStory}_saneado_version_${version}.md`;

// Retornamos el objeto listo para el nodo "Convert to File" o "Write File"
return {
  json: {
    file_name: fileName,
    markdown_content: storyContent
  }
};
